export type ImageKey = keyof typeof images

/** Look up an optimised image asset by key. Throws in dev if the key is missing. */
export function img(key: ImageKey | string): ImageAsset {
  const found = (images as Record<string, ImageAsset>)[key]
  if (!found) {
    if (import.meta.env.DEV) throw new Error(`Unknown image key: "${key}"`)
    return { src: '/images/cta-biryani-1600.webp', width: 1600, height: 1067, alt: '' }
  }
  return found
}
